// Generates src/skills/builtin.generated.ts from src/skills/builtin/<name>/SKILL.md.
// Run: bun scripts/gen-builtin-skills.ts   (a test checks the generated file is current)
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { parseFrontmatter } from "../src/config/frontmatter.ts";

const root = join(import.meta.dir, "..");
const dir = join(root, "src/skills/builtin");
const out: { name: string; description: string; body: string }[] = [];
for (const n of readdirSync(dir).sort()) {
  let text: string;
  try { text = readFileSync(join(dir, n, "SKILL.md"), "utf8"); } catch { continue; }
  const fm = parseFrontmatter(text);
  const d = (fm.data ?? {}) as Record<string, unknown>;
  if (typeof d.name !== "string" || typeof d.description !== "string") throw new Error(`${n}: name and description are required`);
  if (d.name !== n) throw new Error(`${n}: folder and name differ`);
  out.push({ name: d.name, description: d.description, body: fm.body.trim() });
}
writeFileSync(join(root, "src/skills/builtin.generated.ts"),
  "// GENERATED by scripts/gen-builtin-skills.ts from src/skills/builtin/*/SKILL.md. Do not edit by hand.\n" +
  "export const BUILTIN_SKILL_DATA: { name: string; description: string; body: string }[] = " + JSON.stringify(out, null, 2) + ";\n");
console.log(`wrote ${out.length} skills`);
